+        Object snapshot = UNSAFE.getObject(queue, offset);
+        // It's possible that the taker outraced the snapshot above.
+        if (snapshot == null) {
+          if (UNSAFE.compareAndSwapObject(queue, offset, null, task)) {
+            return true;
+          }
+          continue; // Refreshes the snapshot.
+        }
