+      int snapshot = UNSAFE.getIntVolatile(null, countersAddress);
+      int activeWorkers = snapshot >>> ACTIVE_WORKERS_COUNT_BIT_OFFSET;
+      if (activeWorkers >= ACTIVE_WORKERS_COUNT_MAX) {
