-  @SuppressWarnings("unchecked")
-  private void monkeyPatchExistingResources() {
-    if (externalResourceFile == null) {
-      return;
-    }
-
-    try {
-      // Create a new AssetManager instance and point it to the resources installed under
-      // /sdcard
