-    for (String toDelete : libsToDelete) {
-      File fileToDelete = new File(incrementalDir + "/" + toDelete);
-      Log.v("StubApplication", "Deleting " + fileToDelete);
-      if (fileToDelete.exists() && !fileToDelete.delete()) {
